<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { CheckCircle2, Clock3, Plus, ShieldCheck, Trash2, X } from 'lucide-vue-next'
import { approveComplianceRule, createComplianceRule, deleteComplianceRule, evaluateCompliance, fetchComplianceDecisions, fetchComplianceRules, runComplianceMaintenance } from '@/api/cmdb'
import { useAuthStore } from '@/stores/useAuthStore'
import type { ComplianceDecision, ComplianceRule } from '@/features/cmdb/types'

const auth = useAuthStore()
const rules = ref<ComplianceRule[]>([])
const decisions = ref<ComplianceDecision[]>([])
const busy = ref(false)
const message = ref('')
const error = ref('')
const showForm = ref(false)
const form = reactive({ name:'网络设备白名单', action:'allow', type:'mac', value:'', environment:'', projectGroup:'', location:'', vlan:'', description:'', expiresAt:'', reminderHours:24 })
const allowedCount = computed(() => decisions.value.filter(item => item.status === 'allowed' || item.status === 'temporary').length)
const deniedCount = computed(() => decisions.value.filter(item => item.status === 'denied' || item.status === 'unmatched').length)

function actionLabel(value:string) { return ({ allow:'白名单', temporary:'临时授权', deny:'拒绝' } as Record<string,string>)[value] || value }
function statusLabel(value:string) { return ({ allowed:'已放行', temporary:'临时放行', denied:'已拒绝', unmatched:'未匹配', 'not-applicable':'不适用' } as Record<string,string>)[value] || value }
async function load() {
  busy.value = true; error.value = ''
  try { [rules.value, decisions.value] = await Promise.all([fetchComplianceRules(auth.token), fetchComplianceDecisions(auth.token)]) } catch (reason) { error.value = reason instanceof Error ? reason.message : '合规基线加载失败' } finally { busy.value = false }
}
async function create() {
  busy.value = true; error.value = ''
  try { await createComplianceRule(auth.token, { ...form }); showForm.value = false; message.value = '合规规则已创建，等待审批'; await load() } catch (reason) { error.value = reason instanceof Error ? reason.message : '规则创建失败' } finally { busy.value = false }
}
async function approve(item:ComplianceRule) { busy.value = true; try { await approveComplianceRule(auth.token, item.id); await load() } catch (reason) { error.value = reason instanceof Error ? reason.message : '审批失败' } finally { busy.value = false } }
async function remove(item:ComplianceRule) { busy.value = true; try { await deleteComplianceRule(auth.token, item.id); await load() } catch (reason) { error.value = reason instanceof Error ? reason.message : '删除失败' } finally { busy.value = false } }
async function maintenance() {
  busy.value = true
  try {
    const result = await runComplianceMaintenance(auth.token)
    message.value = `临时授权检查 ${result.checked} 条，提醒 ${result.reminded} 条，自动撤销 ${result.expired} 条`
    await load()
  } catch (reason) { error.value = reason instanceof Error ? reason.message : '到期维护执行失败' } finally { busy.value = false }
}async function evaluate() { busy.value = true; try { decisions.value = await evaluateCompliance(auth.token); message.value = `已重新计算 ${decisions.value.length} 条接入决策` } catch (reason) { error.value = reason instanceof Error ? reason.message : '评估失败' } finally { busy.value = false } }
onMounted(load)
</script>

<template>
  <section class="compliance-panel">
    <header><div><ShieldCheck/><span><strong>网络资产合规基线</strong><small>MAC/IP/VLAN 白名单、临时授权和拒绝规则</small></span></div><div><button :disabled="busy" @click="showForm=true"><Plus/>新增规则</button><button :disabled="busy" @click="maintenance"><Clock3/>到期维护</button><button class="primary" :disabled="busy" @click="evaluate"><CheckCircle2/>重新评估</button></div></header>
    <div class="compliance-stats"><article><ShieldCheck/><span>已审批规则<strong>{{rules.filter(item=>item.status==='approved').length}}</strong></span></article><article><CheckCircle2/><span>放行接入<strong>{{allowedCount}}</strong></span></article><article class="warning"><Clock3/><span>待处理/拒绝<strong>{{deniedCount}}</strong></span></article></div>
    <div v-if="message" class="compliance-message">{{message}}</div><div v-if="error" class="compliance-error">{{error}}</div>
    <div class="rule-grid"><article v-for="item in rules" :key="item.id"><header><div><strong>{{item.name}}</strong><span>{{actionLabel(item.action)}} · {{item.type}} · {{item.value}}</span></div><b :data-status="item.status">{{item.status==='approved'?'已审批':'待审批'}}</b></header><p>{{item.description||'无说明'}}</p><dl><div><dt>环境/项目组</dt><dd>{{item.environment||'全部'}} / {{item.projectGroup||'全部'}}</dd></div><div><dt>VLAN</dt><dd>{{item.vlan||'全部'}}</dd></div><div><dt>过期时间</dt><dd>{{item.expiresAt||'长期'}}<template v-if="item.reminderHours"> · 提前 {{item.reminderHours}}h</template></dd></div><div><dt>创建人</dt><dd>{{item.createdBy}}</dd></div></dl><footer><button v-if="item.status!=='approved'" :disabled="busy" @click="approve(item)">审批通过</button><button :disabled="busy" @click="remove(item)"><Trash2/>删除</button></footer></article><div v-if="!rules.length" class="compliance-empty">暂无合规规则</div></div>
    <div class="decision-list"><h4>当前接入决策</h4><div class="decision-head"><span>异常对象</span><span>IP / MAC</span><span>VLAN</span><span>匹配规则</span><span>结果</span></div><div v-for="item in decisions.slice(0,30)" :key="item.id" class="decision-row"><span>{{item.title}}</span><span>{{item.ip||'-'}} / {{item.macAddress||'-'}}</span><span>{{item.vlan||'-'}}</span><span>{{item.ruleName||'未匹配'}}</span><b :data-status="item.status">{{statusLabel(item.status)}}</b></div><div v-if="!decisions.length" class="compliance-empty">暂无未授权接入决策</div></div>
    <div v-if="showForm" class="compliance-modal" @click.self="showForm=false"><form @submit.prevent="create"><header><div><span>COMPLIANCE BASELINE</span><h3>新增合规规则</h3></div><button type="button" @click="showForm=false"><X/></button></header><div class="form-grid"><label><span>规则名称</span><input v-model="form.name" required></label><label><span>动作</span><select v-model="form.action"><option value="allow">白名单</option><option value="temporary">临时授权</option><option value="deny">拒绝</option></select></label><label><span>匹配类型</span><select v-model="form.type"><option value="mac">MAC</option><option value="ip">IP</option><option value="cidr">CIDR</option><option value="vlan">VLAN</option></select></label><label><span>匹配值</span><input v-model="form.value" placeholder="AA:BB:... / 10.0.0.1 / 10.0.0.0/24 / 100" required></label><label><span>环境</span><input v-model="form.environment"></label><label><span>项目组</span><input v-model="form.projectGroup"></label><label><span>位置/机房</span><input v-model="form.location"></label><label><span>VLAN</span><input v-model="form.vlan"></label><label><span>过期时间</span><input v-model="form.expiresAt" placeholder="2026-12-31 23:59:59"></label><label><span>提前提醒小时</span><input v-model.number="form.reminderHours" type="number" min="1"></label><label class="wide"><span>说明</span><input v-model="form.description"></label></div><footer><button type="button" @click="showForm=false">取消</button><button class="primary" type="submit" :disabled="busy">提交审批</button></footer></form></div>
  </section>
</template>

<style scoped>
.compliance-panel{margin-top:14px;border:1px solid #174d78;background:rgba(4,24,43,.72)}.compliance-panel>header{display:flex;justify-content:space-between;align-items:center;padding:14px 18px;border-bottom:1px solid #173d58}.compliance-panel>header>div:first-child{display:flex;align-items:center;gap:8px}.compliance-panel>header svg{width:18px;color:#31cbea}.compliance-panel>header span{display:grid;gap:3px}.compliance-panel>header strong{font-size:12px;font-weight:500}.compliance-panel>header small{font-size:9px;color:#638397}.compliance-panel>header>div:last-child{display:flex;gap:7px}.compliance-panel button{display:flex;align-items:center;gap:5px;border:1px solid #28536c;background:#0b263b;color:#a9c6d9;padding:6px 9px;font-size:9px;cursor:pointer}.compliance-panel button.primary{background:#0b6da5;border-color:#1a93c8;color:#fff}.compliance-panel button:disabled{opacity:.4}.compliance-panel button svg{width:12px}.compliance-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:7px;padding:10px 18px}.compliance-stats article{display:flex;gap:8px;align-items:center;padding:9px;background:#061a2c;border:1px solid #153d57}.compliance-stats svg{width:18px;color:#32c5e8}.compliance-stats span{display:grid;gap:3px;color:#66879b;font-size:9px}.compliance-stats strong{font-size:17px;color:#d5edf8;font-weight:500}.compliance-stats .warning svg{color:#ffc167}.rule-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(270px,1fr));gap:8px;padding:0 18px 12px}.rule-grid article{padding:11px;border:1px solid #17415e;background:#061a2c}.rule-grid article>header{display:flex;justify-content:space-between}.rule-grid article>header strong,.rule-grid article>header span{display:block}.rule-grid article>header span,.rule-grid p{font-size:9px;color:#66879b}.rule-grid b{padding:3px 6px;background:rgba(255,174,72,.12);color:#ffc167;font-size:8px;font-weight:500}.rule-grid b[data-status=approved]{background:rgba(72,216,154,.1);color:#5bdfa1}.rule-grid dl{display:grid;grid-template-columns:1fr 1fr;gap:6px;margin:9px 0}.rule-grid dt{font-size:8px;color:#5e7e93}.rule-grid dd{margin:3px 0 0;font-size:9px;color:#b9d6e5}.rule-grid footer{display:flex;justify-content:flex-end;gap:5px}.decision-list{padding:12px 18px 16px;border-top:1px solid #173d58}.decision-list h4{font-size:10px;margin:0 0 8px}.decision-head,.decision-row{display:grid;grid-template-columns:1.4fr 1.4fr .6fr 1fr .6fr;gap:6px;align-items:center;padding:7px 8px;font-size:8px}.decision-head{background:#08243a;color:#608197}.decision-row{background:#061a2c;border-bottom:1px solid #15374e;color:#9eb9c9}.decision-row b{font-weight:500;color:#61dfa2}.decision-row b[data-status=denied],.decision-row b[data-status=unmatched]{color:#ff8292}.decision-row b[data-status=temporary]{color:#ffc167}.compliance-message,.compliance-error{margin:8px 18px;padding:7px;font-size:9px}.compliance-message{background:rgba(68,214,145,.1);color:#61dfa2}.compliance-error{background:rgba(255,82,104,.1);color:#ff8998}.compliance-empty{padding:18px;text-align:center;color:#638397;font-size:9px}.compliance-modal{position:fixed;inset:0;z-index:80;background:rgba(0,8,16,.78);display:grid;place-items:center}.compliance-modal form{width:min(680px,92vw);max-height:88vh;overflow:auto;background:#041a2e;border:1px solid #246c98}.compliance-modal form>header{display:flex;justify-content:space-between;padding:14px 17px;border-bottom:1px solid #174d78}.compliance-modal h3{margin:4px 0}.compliance-modal header span{font-size:8px;color:#31c6e7;letter-spacing:2px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:9px;padding:14px 17px}.form-grid label{display:grid;gap:4px}.form-grid label.wide{grid-column:1/-1}.form-grid label span{font-size:9px;color:#6b8da2}.form-grid input,.form-grid select{height:31px;border:1px solid #24536f;background:#031525;color:#c4dfed;padding:0 7px}.compliance-modal footer{display:flex;justify-content:flex-end;gap:7px;padding:12px 17px;border-top:1px solid #173d58}@media(max-width:1100px){.compliance-stats{grid-template-columns:1fr}.decision-head,.decision-row{grid-template-columns:1fr 1fr .6fr .8fr .6fr}}
</style>
